    private static void assertCalledBefore(
        List<fflib_InvocationOnMock> invocations,
        Object firstMock,
        String firstMethod,
        Object secondMock,
        String secondMethod
    ) {
        Integer firstIndex = findInvocationIndex(invocations, firstMock, firstMethod, null);
        Integer secondIndex = findInvocationIndex(invocations, secondMock, secondMethod, null);

        System.assertNotEquals(
            -1,
            firstIndex,
            'Expected invocation was not found: ' + firstMethod
        );
        System.assertNotEquals(
            -1,
            secondIndex,
            'Expected invocation was not found: ' + secondMethod
        );
        System.assert(
            firstIndex < secondIndex,
            'Expected ' + firstMethod + ' to be called before ' + secondMethod
        );
    }

    private static void assertCalledBefore(
        List<fflib_InvocationOnMock> invocations,
        SObject expectedSObjectArgument,
        Object firstMock,
        String firstMethod,
        Object secondMock,
        String secondMethod
    ) {
        Integer firstIndex = findInvocationIndex(invocations, firstMock, firstMethod, expectedSObjectArgument);
        Integer secondIndex = findInvocationIndex(invocations, secondMock, secondMethod, null);

        System.assertNotEquals(
            -1,
            firstIndex,
            'Expected invocation was not found: ' + firstMethod
        );
        System.assertNotEquals(
            -1,
            secondIndex,
            'Expected invocation was not found: ' + secondMethod
        );
        System.assert(
            firstIndex < secondIndex,
            'Expected ' + firstMethod + ' to be called before ' + secondMethod
        );
    }

    private static Integer findInvocationIndex(
        List<fflib_InvocationOnMock> invocations,
        Object expectedMock,
        String expectedMethod,
        SObject expectedSObjectArgument
    ) {
        for (Integer i = 0; i < invocations.size(); i++) {
            fflib_InvocationOnMock invocation = invocations[i];
            if (invocation.getMock() != expectedMock) {
                continue;
            }
            if (invocation.getMethod() != expectedMethod) {
                continue;
            }
            if (expectedSObjectArgument != null) {
                List<Object> arguments = invocation.getArguments();
                if (arguments == null || arguments.isEmpty()) {
                    continue;
                }
                if (arguments[0] !== expectedSObjectArgument) {
                    continue;
                }
            }
            return i;
        }
        return -1;
    }
