public with sharing class GiftImportService {
    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();

        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        List<npsp__DataImport__c> stagedImports = new List<npsp__DataImport__c>();

        for (WebGift gift : gifts) {
            ImportResult placeholder = new ImportResult();
            placeholder.success = false;
            results.add(placeholder);

            npsp__DataImport__c dataImport = new npsp__DataImport__c();
            dataImport.npsp__Contact1_Firstname__c = gift == null ? null : gift.firstName;
            dataImport.npsp__Contact1_Lastname__c = gift == null ? null : gift.lastName;
            dataImport.npsp__Contact1_Personal_Email__c = gift == null ? null : gift.email;
            dataImport.npsp__Donation_Amount__c = gift == null ? null : gift.amount;
            dataImport.npsp__Donation_Date__c = gift == null ? null : gift.giftDate;
            dataImport.npsp__Donation_Donor__c = 'Contact1';

            stagedImports.add(dataImport);
        }

        Database.SaveResult[] insertResults = Database.insert(stagedImports, false);

        List<Id> dataImportIdsToProcess = new List<Id>();
        List<Integer> inputIndexesToProcess = new List<Integer>();

        for (Integer i = 0; i < insertResults.size(); i++) {
            if (insertResults[i].isSuccess()) {
                dataImportIdsToProcess.add(insertResults[i].getId());
                inputIndexesToProcess.add(i);
            } else {
                results[i].success = false;
                results[i].errorMessage = formatDmlErrors(insertResults[i].getErrors());
            }
        }

        if (!dataImportIdsToProcess.isEmpty()) {
            processDataImports(dataImportIdsToProcess);

            Map<Id, npsp__DataImport__c> processedImportsById = new Map<Id, npsp__DataImport__c>([
                SELECT
                    Id,
                    npsp__Status__c,
                    npsp__Contact1Imported__c,
                    npsp__DonationImported__c,
                    npsp__FailureInformation__c
                FROM npsp__DataImport__c
                WHERE Id IN :dataImportIdsToProcess
            ]);

            for (Integer i = 0; i < dataImportIdsToProcess.size(); i++) {
                Id dataImportId = dataImportIdsToProcess[i];
                Integer inputIndex = inputIndexesToProcess[i];
                npsp__DataImport__c processedImport = processedImportsById.get(dataImportId);

                ImportResult result = new ImportResult();
                result.success = processedImport != null && processedImport.npsp__Status__c == 'Imported';

                if (processedImport != null) {
                    result.contactId = processedImport.npsp__Contact1Imported__c;
                    result.opportunityId = processedImport.npsp__DonationImported__c;

                    if (!result.success) {
                        result.errorMessage = processedImport.npsp__FailureInformation__c;
                    }
                } else {
                    result.success = false;
                    result.errorMessage = 'NPSP Data Import record was not found after processing.';
                }

                results[inputIndex] = result;
            }
        }

        return results;
    }

    private static void processDataImports(List<Id> dataImportIds) {
        npsp.BDI_DataImport_API.importDI(dataImportIds);
    }

    private static String formatDmlErrors(Database.Error[] errors) {
        List<String> messages = new List<String>();

        if (errors != null) {
            for (Database.Error error : errors) {
                if (error == null) {
                    continue;
                }

                String message = error.getMessage();

                if (error.getFields() != null && !error.getFields().isEmpty()) {
                    message += ' Fields: ' + String.join(error.getFields(), ', ');
                }

                messages.add(message);
            }
        }

        return messages.isEmpty() ? 'Unable to create NPSP Data Import staging record.' : String.join(messages, ' | ');
    }
}
